    async function saveProfilePhone(){var input=el('profilePhone'),button=el('saveProfilePhone'),status=el('profilePhoneStatus');button.disabled=true;try{var result=await api('/api/profile/phone',{phone:input.value.trim()});state.user.phone=result.phone;renderNotificationSettings();status.textContent='\u0422\u0435\u043B\u0435\u0444\u043E\u043D \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D. \u0422\u0435\u043F\u0435\u0440\u044C \u043F\u043E \u043D\u0435\u043C\u0443 \u043C\u043E\u0436\u043D\u043E \u0432\u0445\u043E\u0434\u0438\u0442\u044C \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435.';toast('\u0422\u0435\u043B\u0435\u0444\u043E\u043D \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043D')}catch(error){status.textContent='\u041E\u0448\u0438\u0431\u043A\u0430: '+error.message;toast(error.message)}finally{button.disabled=false}}
