    function roleLabel(role){return {owner:'Координатор',employee:'Сотрудник СКП',coordinator:'Координатор',executive:'Руководитель / наблюдатель',contractor_manager:'Менеджер',performer:'Исполнитель'}[role]||'Участник'}
