    function organizationLabel(value){return {customer:'\u041E\u041E\u041E \u00AB\u0421\u041A\u041F \u201E\u0422\u0430\u0442\u043D\u0435\u0444\u0442\u044C - \u0410\u043A \u0411\u0430\u0440\u0441\u201C\u00BB',contractor:'\u041E\u041E\u041E \u00AB\u041C\u0435\u0433\u0430 \u0428\u043E\u0443\u00BB',performer:'\u0418\u0441\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C / \u0430\u0440\u0442\u0438\u0441\u0442'}[value]||value||'\u041D\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u0430'}
