    function canCreateEvents(){return !!(state.user&&state.user.organization==='customer')}
    function canCreateCalculations(){return !!(state.user&&(['owner','employee','coordinator'].includes(state.user.role)||(state.user.organization==='contractor'&&state.user.role==='contractor_manager')))}
    function todayKey(){var now=new Date();return now.getFullYear()+'-'+pad2(now.getMonth()+1)+'-'+pad2(now.getDate())}
    function isPastEventDate(value){var key=String(value||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(key)&&key<todayKey()}
    async function loadWorkspace(){var data=await api('/api/workspace');state.activeSeason=data.activeSeason||null;state.drafts=data.events||[];state.contractorPeople=data.contractorPeople||[];state.requests=data.calculations||[];state.catalogs=data.catalogs||[];state.standardEstimates=data.standardEstimates||[];state.servicesByTeam=data.servicesByTeam||{};state.services=data.services||[]}
    async function refreshWorkspace(message){await loadWorkspace();recalculateSavedRequests();renderNext();renderMatchOptions();renderMatches();renderCalendarImports();renderCatalogVersions();renderStandardEstimates();renderCategories();renderServices();renderRequests();renderApprovals();renderSpecs();renderSpentSummary();renderCalculationAdminTools();el('matchesCount').textContent=allEventChoices().length;el('servicesCount').textContent=state.services.length;el('draftsCount').textContent=state.requests.length;if(message)toast(message)}

    function renderNext(){var now=new Date(),matches=state.drafts.filter(function(event){return event.type==='match'&&event.date}).sort(function(left,right){return String(left.date).localeCompare(String(right.date))});var next=matches.find(function(event){return new Date(event.date)>=now})||matches[0];if(!next){el('nextGame').innerHTML='<div><span class="eyebrow">\u041A\u0430\u043B\u0435\u043D\u0434\u0430\u0440\u044C</span><h3>\u041C\u0430\u0442\u0447\u0438 \u0435\u0449\u0451 \u043D\u0435 \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043D\u044B</h3><p>\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u0443 \u0438 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435 Excel \u0441 \u043A\u0430\u043B\u0435\u043D\u0434\u0430\u0440\u0451\u043C.</p></div>';return}var parsed=new Date(next.date),time=String(next.date).slice(11,16);el('nextGame').innerHTML='<div><span class="eyebrow">\u0411\u043B\u0438\u0436\u0430\u0439\u0448\u0438\u0439 \u0434\u043E\u043C\u0430\u0448\u043D\u0438\u0439 \u043C\u0430\u0442\u0447</span><h3>'+esc(next.title)+'</h3><p>'+esc(next.place)+'</p></div><div class="date-badge">'+String(parsed.getDate()).padStart(2,'0')+'<small>'+months[parsed.getMonth()].slice(0,3)+', '+time+'</small></div>'}
    function eventOption(m){return '<option value="match:'+esc(m.id)+'">'+esc(m.title)+' - '+dateLabel(m)+'</option>'}
    function draftLabel(d){var details=[];if(d.place)details.push(d.place);if(d.date){var parsed=new Date(d.date);details.push(isNaN(parsed.getTime())?d.date:parsed.toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}))}return d.title+(details.length?' - '+details.join(', '):'')}
    function renderMatchOptions(){el('eventMatch').innerHTML='<option value="">\u041C\u0430\u0442\u0447\u0438 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u044E\u0442\u0441\u044F \u0438\u0437 Excel</option>';if(!state.matches.length){el('eventType').value='event';el('matchField').classList.add('hidden');el('customFields').classList.remove('hidden')}renderServiceEventOptions();renderBatchEvents()}
    function renderServiceEventOptions(){var select=el('serviceEvent');if(!select)return;var previous=select.value;var query=normalizeSearch(el('serviceEventSearch')?el('serviceEventSearch').value:'');var terms=query?query.split(' '):[];var eventFilter=el('serviceEventTypeFilter')?el('serviceEventTypeFilter').value:'all';var choices=allEventChoices().filter(function(event){if(!eventMatchesFilter(event.team,eventFilter))return false;if(isPastEventDate(event.date)&&!state.showPastEvents)return false;var haystack=normalizeSearch(event.title+' '+event.details);return terms.every(function(term){return haystack.includes(term)})});select.innerHTML=choices.map(function(event){var past=isPastEventDate(event.date);return '<option'+(past?' class="past-option"':'')+' value="'+esc(event.value)+'">'+esc((past?'\u041F\u0420\u041E\u0428\u0415\u0414\u0428\u0415\u0415 - ':'')+event.title+(event.details?' - '+event.details:''))+'</option>'}).join('')||'<option value="">\u0421\u043E\u0431\u044B\u0442\u0438\u044F \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u044B</option>';if(choices.some(function(event){return event.value===previous}))select.value=previous;else if(choices.length)select.value=choices[0].value;applyServicesForSelectedEvent(false)}
    function pad2(value){return String(value).padStart(2,'0')}
    function normalizeHeader(value){return String(value==null?'':value).toLowerCase().replace(/\u0451/g,'\u0435').replace(/[^a-z\u0430-\u044F0-9]+/g,'')}
    function excelDate(value){
      if(value instanceof Date&&!isNaN(value.getTime()))return value.getFullYear()+'-'+pad2(value.getMonth()+1)+'-'+pad2(value.getDate());
      if(typeof value==='number'&&window.XLSX){var parsed=XLSX.SSF.parse_date_code(value);if(parsed)return parsed.y+'-'+pad2(parsed.m)+'-'+pad2(parsed.d)}
      var text=String(value||'').trim();var ru=text.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})$/);if(ru)return ru[3]+'-'+pad2(ru[2])+'-'+pad2(ru[1]);var iso=text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);if(iso)return iso[1]+'-'+pad2(iso[2])+'-'+pad2(iso[3]);return ''
    }
    function excelTime(value){
      if(value instanceof Date&&!isNaN(value.getTime()))return pad2(value.getHours())+':'+pad2(value.getMinutes());
      if(typeof value==='number'){var minutes=Math.round((value-Math.floor(value))*1440)%1440;return pad2(Math.floor(minutes/60))+':'+pad2(minutes%60)}
      var text=String(value||'').trim();var match=text.match(/^(\d{1,2}):(\d{2})/);if(!match)return '';var hour=Number(match[1]),minute=Number(match[2]);if(hour>23||minute>59)return '';return pad2(hour)+':'+pad2(minute)
    }
    function rowValue(row,headers,names){for(var i=0;i<names.length;i++){var target=normalizeHeader(names[i]);var index=headers.findIndex(function(header){return header===target||header.startsWith(target)||target.startsWith(header)});if(index>=0&&row[index]!=null)return row[index]}return ''}
    function teamLabel(value){return {'ak-bars':'\u0410\u043A \u0411\u0430\u0440\u0441',bars:'\u0411\u0430\u0440\u0441',irbis:'\u0418\u0440\u0431\u0438\u0441'}[value]||value}
    function enhanceOwnerSeason(){var calendar=el('calendarIcs'),catalog=el('catalogExcel'),host=el('seasonTools');if(!calendar||!catalog||!host)return;var cards=[catalog.closest('.card'),calendar.closest('.card')];if(!state.isOwner){cards.forEach(function(card){if(card)card.classList.add('hidden')});return}cards.forEach(function(card,index){if(!card)return;card.classList.remove('hidden');var heading=card.querySelector('h3');if(heading){heading.textContent=index===0?'\u0428\u0430\u0433 2 - \u0411\u0430\u0437\u0430 \u0443\u0441\u043B\u0443\u0433 \u0438 \u0442\u0435\u043D\u0434\u0435\u0440\u043D\u044B\u0445 \u0446\u0435\u043D':'\u0428\u0430\u0433 3 - \u041A\u0430\u043B\u0435\u043D\u0434\u0430\u0440\u0438 \u043C\u0430\u0442\u0447\u0435\u0439';heading.dataset.seasonStep='1'}host.appendChild(card)})}
    function enhanceCalendarUpload(){var input=el('calendarIcs');if(!input||el('downloadCalendarTemplate'))return;input.accept='.xlsx,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel';var paragraph=input.parentElement.querySelector('.import-help');if(paragraph)paragraph.textContent='\u041E\u0434\u0438\u043D \u0440\u0430\u0437 \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u0441\u0435\u0437\u043E\u043D\u0430: \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u0443 \u0438 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435 Excel. \u041E\u0434\u043D\u0430 \u0441\u0442\u0440\u043E\u043A\u0430 - \u043E\u0434\u0438\u043D \u0434\u043E\u043C\u0430\u0448\u043D\u0438\u0439 \u043C\u0430\u0442\u0447. \u0414\u0430\u0442\u0430 \u0438 \u0432\u0440\u0435\u043C\u044F \u0437\u0430\u043F\u043E\u043B\u043D\u044F\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E.';input.insertAdjacentHTML('beforebegin','<div style="display:flex;gap:8px;margin:10px 0"><button id="downloadCalendarTemplate" class="btn small secondary" type="button">\u0421\u043A\u0430\u0447\u0430\u0442\u044C \u0448\u0430\u0431\u043B\u043E\u043D \u043A\u0430\u043B\u0435\u043D\u0434\u0430\u0440\u044F</button></div>')}
    function enhanceCatalogUpload(){var input=el('catalogExcel');if(!input||el('downloadCatalogTemplate'))return;var paragraph=input.parentElement.querySelector('.import-help');if(paragraph)paragraph.textContent='\u0415\u0434\u0438\u043D\u044B\u0439 \u043A\u0430\u0442\u0430\u043B\u043E\u0433 \u0441\u0435\u0437\u043E\u043D\u0430 \u0434\u043B\u044F \u0410\u043A \u0411\u0430\u0440\u0441\u0430, \u0411\u0430\u0440\u0441\u0430 \u0438 \u0418\u0440\u0431\u0438\u0441\u0430. \u0421\u043A\u0430\u0447\u0430\u0439\u0442\u0435 Excel-\u0448\u0430\u0431\u043B\u043E\u043D \u0438 \u0432\u043D\u0435\u0441\u0438\u0442\u0435 \u043F\u043E\u0437\u0438\u0446\u0438\u0438, \u043E\u043F\u0438\u0441\u0430\u043D\u0438\u044F, \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u0438\u044F \u0438 \u0442\u0435\u043D\u0434\u0435\u0440\u043D\u044B\u0435 \u0446\u0435\u043D\u044B. \u041A\u0430\u0436\u0434\u0430\u044F \u0441\u0442\u0440\u043E\u043A\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0441\u0442\u0430\u043D\u0435\u0442 \u0443\u0441\u043B\u0443\u0433\u043E\u0439 \u0432\u043E \u0432\u0441\u0435\u0445 \u0440\u0430\u0441\u0447\u0451\u0442\u0430\u0445.';input.insertAdjacentHTML('beforebegin','<div style="display:flex;gap:8px;margin:10px 0"><button id="downloadCatalogTemplate" class="btn small secondary" type="button">\u0421\u043A\u0430\u0447\u0430\u0442\u044C \u043F\u0443\u0441\u0442\u043E\u0439 \u0448\u0430\u0431\u043B\u043E\u043D</button></div>')}
    function teamForEventValue(value){if(String(value||'').startsWith('match:'))return 'ak-bars';if(String(value||'').startsWith('draft:')){var item=state.drafts.find(function(event){return String(event.id)===String(value).slice(6)});return item&&item.team||''}return ''}
