        var price=parseCatalogNumber(rowValue(row,headers,['\u0426\u0435\u043D\u0430 \u0437\u0430 \u0435\u0434\u0438\u043D\u0438\u0446\u0443','\u0426\u0435\u043D\u0430 \u0435\u0434\u0438\u043D\u0438\u0446\u044B','\u041F\u0440\u0435\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u0446\u0435\u043D\u0430','\u0426\u0435\u043D\u0430','\u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0437\u0430 \u0435\u0434\u0438\u043D\u0438\u0446\u0443','\u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C']));
        var artist=/\u0430\u0433\u0435\u043D\u0442\u0441\u043A.*10|\u0433\u043E\u043D\u043E\u0440\u0430\u0440.*10/i.test(name+' '+description)||unit.includes('%');
