        if(combined){pushService(baseId+'-RAO',position+'-\u0420\u0410\u041E','\u041E\u0444\u043E\u0440\u043C\u043B\u0435\u043D\u0438\u0435 \u043F\u0440\u0430\u0432 \u0420\u0410\u041E',price,'music-rights');pushService(baseId+'-VOIS',position+'-\u0412\u041E\u0418\u0421','\u041E\u0444\u043E\u0440\u043C\u043B\u0435\u043D\u0438\u0435 \u043F\u0440\u0430\u0432 \u0412\u041E\u0418\u0421',price,'music-rights')}
