      var html='',current='';events.forEach(function(event){var parsed=new Date(event.date),key=isNaN(parsed.getTime())?'Без даты':months[parsed.getMonth()]+' '+parsed.getFullYear();if(key!==current){current=key;html+='<h3 class="month">'+esc(key)+'</h3>'}html+=eventCard(event)});
