const encoder = new TextEncoder();
const XLSX_SCRIPT_URL = 'https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';
const EXCELJS_SCRIPT_URL = 'https://cdn.jsdelivr.net/npm/exceljs@4.4.0/dist/exceljs.min.js';

async function validateMiniAppData(initData, botToken, maxAgeSeconds = 86400) {
  const params = new URLSearchParams(initData);
  const receivedHash = params.get('hash');
  if (!receivedHash) return null;

  params.delete('hash');
  const dataCheckString = Array.from(params.entries())
    .sort((left, right) => left[0].localeCompare(right[0]))
    .map((entry) => entry[0] + '=' + entry[1])
    .join('\n');

  const webAppKey = await crypto.subtle.importKey(
    'raw',
    encoder.encode('WebAppData'),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  const secretBytes = await crypto.subtle.sign('HMAC', webAppKey, encoder.encode(botToken));
  const secretKey = await crypto.subtle.importKey(
    'raw',
    secretBytes,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  const calculatedBytes = await crypto.subtle.sign('HMAC', secretKey, encoder.encode(dataCheckString));
  const calculatedHash = Array.from(new Uint8Array(calculatedBytes))
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join('');

  if (!constantTimeEqual(calculatedHash, receivedHash)) return null;
  const authDate = Number(params.get('auth_date') || 0);
  const now = Math.floor(Date.now() / 1000);
  if (!authDate || Math.abs(now - authDate) > maxAgeSeconds) return null;

  try {
    return JSON.parse(params.get('user') || 'null');
  } catch {
    return null;
  }
}

function constantTimeEqual(left, right) {
  if (left.length !== right.length) return false;
  let result = 0;
  for (let index = 0; index < left.length; index += 1) {
    result |= left.charCodeAt(index) ^ right.charCodeAt(index);
  }
  return result === 0;
}

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'content-type': 'application/json; charset=UTF-8',
      'cache-control': 'no-store',
      'x-content-type-options': 'nosniff',
    },
  });
}

function ownerIds(env) {
  return String(env.ALLOWED_TELEGRAM_IDS || '').split(/[\s,;]+/).filter(Boolean);
}

function maxOwnerIds(env) {
  return String(env.ALLOWED_MAX_IDS || '').split(/[\s,;]+/).filter(Boolean);
}

function allOwnerUserIds(env) {
  return ownerIds(env).concat(maxOwnerIds(env).map((id) => 'max:' + id));
}

function isOwner(env, userId) {
  const id = String(userId || '');
  if (id.startsWith('max:')) return maxOwnerIds(env).includes(id.slice(4));
  return ownerIds(env).includes(id);
}

async function sha256Hex(value) {
  const bytes = await crypto.subtle.digest('SHA-256', encoder.encode(String(value || '')));
  return Array.from(new Uint8Array(bytes)).map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

function randomDigits(length = 6) {
  const bytes = new Uint32Array(1); crypto.getRandomValues(bytes);
  return String(bytes[0] % Math.pow(10, length)).padStart(length, '0');
}

function randomToken() {
  const bytes = new Uint8Array(32); crypto.getRandomValues(bytes);
  return Array.from(bytes).map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

async function authenticateTelegram(request, env) {
  let body;
  try {
    body = await request.json();
  } catch {
    return { error: jsonResponse({ ok: false, error: '\u041D\u0435\u043A\u043E\u0440\u0440\u0435\u043A\u0442\u043D\u044B\u0439 \u0437\u0430\u043F\u0440\u043E\u0441' }, 400) };
  }

  if (body.webToken) {
    await ensureSchema(env);
    const tokenHash = await sha256Hex(body.webToken);
    const now = Math.floor(Date.now() / 1000);
    const session = await env.DB.prepare("SELECT s.user_id, u.first_name, u.last_name, u.username FROM web_sessions s JOIN users u ON u.telegram_id=s.user_id WHERE s.token_hash=? AND s.expires_at>? AND u.status='active'").bind(tokenHash, now).first();
    if (!session) return { error: jsonResponse({ ok: false, error: 'Срок браузерной сессии истёк. Войдите ещё раз.' }, 401) };
    await env.DB.prepare('UPDATE web_sessions SET last_used_at=CURRENT_TIMESTAMP WHERE token_hash=?').bind(tokenHash).run();
    return { body, user: { id: String(session.user_id), raw_id: String(session.user_id), platform: 'web', first_name: session.first_name || '', last_name: session.last_name || '', username: session.username || '' } };
  }

  const platform = body.platform === 'max' ? 'max' : 'telegram';
  const token = platform === 'max' ? env.MAX_BOT_TOKEN : env.TELEGRAM_BOT_TOKEN;
  if (!token) {
    return { error: jsonResponse({ ok: false, error: platform === 'max' ? '\u0422\u043E\u043A\u0435\u043D MAX \u043D\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D' : '\u0422\u043E\u043A\u0435\u043D Telegram-\u0431\u043E\u0442\u0430 \u043D\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D' }, 503) };
  }

  const user = await validateMiniAppData(body.initData || '', token, platform === 'max' ? 3600 : 86400);
  if (!user) {
    return { error: jsonResponse({ ok: false, error: (platform === 'max' ? 'MAX' : 'Telegram') + ' \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043B \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F' }, 401) };
  }
  const rawId = String(user.id);
  return {
    body,
    user: {
      id: platform === 'max' ? 'max:' + rawId : rawId,
      raw_id: rawId,
      platform,
      first_name: user.first_name || '',
      last_name: user.last_name || '',
      username: user.username || '',
    },
  };
}

let schemaReadyPromise = null;

async function ensureSchema(env) {
  if (!schemaReadyPromise) schemaReadyPromise = initializeSchema(env).catch((error) => { schemaReadyPromise = null; throw error; });
  return schemaReadyPromise;
}

