        if (!eventId) return jsonResponse({ ok: false, error: '\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u0435' }, 400);
        const calculationTeam = await teamForCalculationEvent(env, eventId);
        const items = await normalizeCalculationItems(auth.body.items, env, calculationTeam || 'ak-bars');
        const total = Math.round(items.reduce((sum, item) => sum + item.line_total, 0) * 100) / 100;
        const existing = await env.DB.prepare('SELECT * FROM calculations WHERE id=? AND deleted_at IS NULL').bind(calculationId).first();
        if (existing) {
          const editableStatuses = ['draft', 'returned'];
          const creatorEdit = String(existing.created_by) === String(auth.user.id) && editableStatuses.includes(existing.status);
          const factualEdit = existing.status === 'approved' && auth.databaseUser.role === 'owner';
          if (!creatorEdit && !factualEdit) return jsonResponse({ ok: false, error: 'Редактировать расчёт может его автор до согласования или координатор-владелец после согласования' }, 403);
        }
        const organization = existing ? existing.organization : cleanText(auth.databaseUser.organization, 80);
        const status = existing ? existing.status : 'draft';
