        if (auth.error) return auth.error;
        const calculationId = cleanText(auth.body.id, 100);
        const action = cleanText(auth.body.action, 40);
        const comment = cleanText(auth.body.comment, 1500);
        const calculation = await env.DB.prepare('SELECT * FROM calculations WHERE id=? AND deleted_at IS NULL').bind(calculationId).first();
        if (!calculation) return jsonResponse({ ok: false, error: '\u0420\u0430\u0441\u0447\u0451\u0442 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D' }, 404);
        const route = approvalRouteFor(calculation, auth.databaseUser);
        const actorRole = auth.databaseUser.role;
        const actorId = String(auth.user.id);
        const creatorId = String(calculation.created_by);
        const isCreator = actorId === creatorId;
        let nextStatus = '';
        let nextApproverRole = calculation.current_approver_role || '';
        let allowed = false;
        if (action === 'send_approval' && ['draft', 'returned'].includes(calculation.status)) {
          allowed = isCreator && canCreateCalculationsForRole(auth.databaseUser);
          nextStatus = route.route === 'vil_to_gleb' ? 'approval' : 'coordinator_review';
          nextApproverRole = route.currentRole;
        } else if (action === 'approve_stage' && calculation.status === 'coordinator_review') {
          allowed = actorRole === calculation.current_approver_role && !isCreator;
          if (route.route === 'employee_vil_gleb') { nextStatus = 'approval'; nextApproverRole = 'coordinator'; }
          else { nextStatus = 'approved'; nextApproverRole = ''; }
        } else if (action === 'approve' && calculation.status === 'approval') {
          allowed = actorRole === calculation.current_approver_role && !isCreator;
          nextStatus = 'approved'; nextApproverRole = '';
        } else if (action === 'return' && ['coordinator_review', 'approval'].includes(calculation.status)) {
          allowed = actorRole === calculation.current_approver_role && !isCreator;
          nextStatus = 'returned'; nextApproverRole = '';
        } else if (action === 'reopen' && ['returned', 'cancelled'].includes(calculation.status)) {
          allowed = isCreator; nextStatus = 'draft'; nextApproverRole = '';
        } else if (action === 'cancel' && ['draft', 'coordinator_review', 'approval', 'returned'].includes(calculation.status)) {
          allowed = isCreator || actorRole === 'owner'; nextStatus = 'cancelled'; nextApproverRole = '';
        }
        if (!nextStatus) return jsonResponse({ ok: false, error: '\u0422\u0430\u043A\u043E\u0439 \u043F\u0435\u0440\u0435\u0445\u043E\u0434 \u0441\u0435\u0439\u0447\u0430\u0441 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D' }, 409);
        if (!allowed) return jsonResponse({ ok: false, error: '\u041D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u043F\u0440\u0430\u0432 \u0434\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F' }, 403);
