        if (action === 'send_approval') await notifyRoles(env, [nextApproverRole], 'Новая заявка на согласование\n' + baseText, [actorId]);
        if (action === 'approve_stage' && nextStatus === 'approval') {
          await notifyCalculationCreator(env, calculation, 'Первый этап согласован. Заявка передана второму координатору.\n' + baseText, actorId);
          await notifyRoles(env, [nextApproverRole], 'Заявка ждёт вашего согласования\n' + baseText, [actorId, creatorId]);
        }
