        if (preference === 'max' && !hasMax) return jsonResponse({ ok: false, error: 'MAX \u043D\u0435 \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043D \u043A \u0432\u0430\u0448\u0435\u043C\u0443 \u043F\u0440\u043E\u0444\u0438\u043B\u044E' }, 400);
